import{sceneLooks,backgroundKinds,createBackgroundLayer,paintSceneSky,paintBackgroundLayers,validateSceneStyle}from'./scene-style.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function openLookEditor({project,onApply,notify,onPreview}){const draft={sceneLook:project.sceneLook||null,backgroundLayers:structuredClone(project.backgroundLayers||[]),style3d:structuredClone(project.style3d||{surface:'lowpoly',detail:'balanced',shadows:true,fog:.35}),backgroundAsset:project.backgroundAsset},three=project.dimension==='3d';let selected=draft.backgroundLayers[0]?.id,applied=false,pending=0,disposed=false;const d=document.createElement('dialog');d.className='editor-dialog look-editor';d.innerHTML=`<div class="dialog-top"><h2>Backgrounds & style</h2><button id="close-look" aria-label="Close backgrounds and style">×</button></div><div class="look-presets">${Object.entries(sceneLooks).map(([id,l])=>`<button data-look="${id}"><span style="background:linear-gradient(${l.sky},${l.horizon})"></span>${l.name}</button>`).join('')}</div>${three?`<h3>3D style</h3><div class="look-choice"><button data-surface="lowpoly">Low Poly</button><button data-surface="smooth">Smooth</button></div><label>Shape detail<select id="look-detail"><option value="chunky">Chunky</option><option value="balanced">Balanced</option><option value="fine">Fine</option></select></label><label class="check"><input id="look-shadows" type="checkbox">Soft shadows</label><label>Distance mist<input id="look-fog" type="range" min="0" max="1" step=".05"></label><label>Background image<input id="look-backdrop" type="file" accept="image/png,image/jpeg,image/webp"></label><button id="remove-look-backdrop">Remove background image</button><p>Low Poly changes the shading and shape detail. It works on characters, spheres, trees, and rocks.</p>`:`<canvas id="look-preview" width="960" height="540" aria-label="Background preview. Drag the selected layer to move it."></canvas><p>Drag the selected background in the preview to move it.</p><div class="look-add">${Object.entries(backgroundKinds).filter(([k])=>k!=='image').map(([k,v])=>`<button data-add-background="${k}">+ ${v}</button>`).join('')}<label class="look-import">+ Import background sprite<input id="look-import" type="file" accept="image/png,image/jpeg,image/webp" multiple></label></div><div id="look-layers"></div><div id="look-fields"></div>`}<footer class="look-footer"><button id="cancel-look">Cancel</button><button id="save-look" class="primary">Apply style</button></footer>`;document.body.append(d);const $=s=>d.querySelector(s);function preview(){d.querySelectorAll('[data-look]').forEach(b=>b.classList.toggle('active',draft.sceneLook===b.dataset.look));d.querySelectorAll('[data-surface]').forEach(b=>b.classList.toggle('active',draft.style3d.surface===b.dataset.surface));if(three){onPreview?.(structuredClone(draft));return}const canvas=$('#look-preview'),ctx=canvas.getContext('2d'),p={...project,...draft,width:960,height:540};ctx.clearRect(0,0,960,540);ctx.fillStyle='#8fbdd8';ctx.fillRect(0,0,960,540);paintSceneSky(ctx,p);paintBackgroundLayers(ctx,p,{x:0,y:0,w:960,h:540});const l=draft.backgroundLayers.find(l=>l.id===selected);if(l){ctx.strokeStyle='#f5a524';ctx.lineWidth=3;ctx.setLineDash([10,7]);ctx.strokeRect(l.x*9.6,l.y*5.4,l.w*9.6,l.h*5.4);ctx.setLineDash([])}}function layers() {if(three)return;$('#look-layers').innerHTML=draft.backgroundLayers.map((l,i)=>`<div class="look-layer"><button data-layer="${esc(l.id)}" class="${l.id===selected?'active':''}">${esc(l.name)}</button><button data-order="${i}" data-dir="-1" aria-label="Move ${esc(l.name)} behind" ${i===0?'disabled':''}>↓</button><button data-order="${i}" data-dir="1" aria-label="Move ${esc(l.name)} in front" ${i===draft.backgroundLayers.length-1?'disabled':''}>↑</button><button data-remove-layer="${i}" aria-label="Remove ${esc(l.name)}">×</button></div>`).join('');d.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{selected=b.dataset.layer;layers();fields();preview()});d.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{const i=+b.dataset.order,j=i+(+b.dataset.dir);[draft.backgroundLayers[i],draft.backgroundLayers[j]]=[draft.backgroundLayers[j],draft.backgroundLayers[i]];layers();preview()});d.querySelectorAll('[data-remove-layer]').forEach(b=>b.onclick=()=>{draft.backgroundLayers.splice(+b.dataset.removeLayer,1);selected=draft.backgroundLayers[0]?.id;layers();fields();preview()})}function fields(){if(three)return;const l=draft.backgroundLayers.find(l=>l.id===selected);$('#look-fields').innerHTML=l?`<label>Name<input data-bg-field="name" maxlength="80" value="${esc(l.name)}"></label><div class="look-numbers">${[['x','Left %'],['y','Top %'],['w','Width %'],['h','Height %']].map(([k,v])=>`<label>${v}<input type="number" data-bg-field="${k}" value="${l[k]}" min="${k==='x'||k==='y'?-200:5}" max="${k==='x'||k==='y'?200:400}"></label>`).join('')}</div><label>See-through ← → solid<input type="range" data-bg-field="opacity" min="0" max="1" step=".05" value="${l.opacity}"></label><label>When the camera moves<select id="background-motion"><option value="0">Stay still</option><option value="0.15">Move a little</option><option value="0.5">Move halfway</option><option value="1">Move with the world</option></select></label><label class="check"><input type="checkbox" data-bg-field="repeat" ${l.repeat?'checked':''}>Repeat across the scene</label><label class="check"><input type="checkbox" data-bg-field="visible" ${l.visible?'checked':''}>Show this layer</label><details><summary>Advanced</summary><label>Camera movement amount<input data-bg-field="parallax" type="number" min="0" max="1" step=".05" value="${l.parallax}"></label><label>Drift left ← → right<input data-bg-field="scrollSpeed" type="range" min="-200" max="200" step="5" value="${l.scrollSpeed}"></label></details>`:'Add clouds, scenery, or your own sprite. Backgrounds never block the player.';if(!l)return;$('#background-motion').value=String([0,.15,.5,1].reduce((a,b)=>Math.abs(a-l.parallax)<Math.abs(b-l.parallax)?a:b));$('#background-motion').onchange=e=>{l.parallax=+e.target.value;fields();preview()};d.querySelectorAll('[data-bg-field]').forEach(input=>input.oninput=()=>{const key=input.dataset.bgField,value=input.type==='checkbox'?input.checked:input.type==='number'||input.type==='range'?Number(input.value):input.value;if(typeof value==='number'&&!Number.isFinite(value))return;l[key]=value;if(['x','y'].includes(key))l[key]=Math.max(-200,Math.min(200,value));if(['w','h'].includes(key))l[key]=Math.max(5,Math.min(400,value));if(key==='parallax')l[key]=Math.max(0,Math.min(1,value));if(key==='name')layers();preview()})}
 async function image(file){if(file.size>1500000||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choose a PNG, JPEG or WebP under 1.5 MB.');return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read the image.'));r.readAsDataURL(file)})}async function importFiles(input,backdrop=false){pending++;$('#save-look').disabled=true;try{for(const f of input.files){if(!backdrop&&draft.backgroundLayers.length>=20)throw Error('Keep backgrounds to 20 layers or fewer.');const asset=await image(f);if(disposed)return;if(JSON.stringify({...project,...draft}).length+asset.length>4000000)throw Error('Use smaller images or remove a background so this project fits on your device.');if(backdrop)draft.backgroundAsset=asset;else{const l=createBackgroundLayer('image');l.name=f.name.slice(0,80);l.asset=asset;draft.backgroundLayers.push(l);selected=l.id}}layers();fields();preview()}catch(e){notify(e.message)}finally{pending--;if(!disposed)$('#save-look').disabled=!!pending}}
 d.querySelectorAll('[data-look]').forEach(b=>b.onclick=()=>{draft.sceneLook=b.dataset.look;if(three){draft.style3d.fog=sceneLooks[draft.sceneLook].fog;$('#look-fog').value=draft.style3d.fog}if(!three&&!draft.backgroundLayers.length){for(const kind of draft.sceneLook==='moonlight'?['stars','mountains']:draft.sceneLook==='forest'?['clouds','mountains','trees']:['clouds','mountains'])draft.backgroundLayers.push(createBackgroundLayer(kind));selected=draft.backgroundLayers[0]?.id;layers();fields()}preview()});if(three){$('#look-detail').value=draft.style3d.detail;$('#look-shadows').checked=draft.style3d.shadows;$('#look-fog').value=draft.style3d.fog;d.querySelectorAll('[data-surface]').forEach(b=>b.onclick=()=>{draft.style3d.surface=b.dataset.surface;preview()});$('#look-detail').onchange=e=>{draft.style3d.detail=e.target.value;preview()};$('#look-shadows').onchange=e=>{draft.style3d.shadows=e.target.checked;preview()};$('#look-fog').oninput=e=>{draft.style3d.fog=+e.target.value;preview()};$('#look-backdrop').onchange=()=>importFiles($('#look-backdrop'),true);$('#remove-look-backdrop').onclick=()=>{draft.backgroundAsset=undefined;preview()}}else{d.querySelectorAll('[data-add-background]').forEach(b=>b.onclick=()=>{if(draft.backgroundLayers.length>=20){notify('Keep backgrounds to 20 layers or fewer.');return}const l=createBackgroundLayer(b.dataset.addBackground);draft.backgroundLayers.push(l);selected=l.id;layers();fields();preview()});$('#look-import').onchange=()=>importFiles($('#look-import'));let drag=null;const canvas=$('#look-preview');canvas.onpointerdown=e=>{const l=draft.backgroundLayers.find(l=>l.id===selected);if(!l)return;drag={l,x:e.clientX,y:e.clientY,ox:l.x,oy:l.y};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;const r=canvas.getBoundingClientRect();drag.l.x=Math.round(Math.max(-200,Math.min(200,drag.ox+(e.clientX-drag.x)/r.width*100)));drag.l.y=Math.round(Math.max(-200,Math.min(200,drag.oy+(e.clientY-drag.y)/r.height*100)));preview()};canvas.onpointerup=canvas.onpointercancel=()=>{drag=null;fields()};window.addEventListener('playform-asset-ready',preview)}
 $('#save-look').onclick=()=>{if(pending)return;if(!validateSceneStyle(draft)){notify('Check background sizes and movement values.');return}onApply(structuredClone(draft));applied=true;d.close()};$('#cancel-look').onclick=$('#close-look').onclick=()=>d.close();d.onclose=()=>{disposed=true;window.removeEventListener('playform-asset-ready',preview);if(!applied)onPreview?.(null);d.remove()};layers();fields();preview();d.showModal();return d}
